export function mountAgentIteration(){
 if(agentIterationVersion==='baseline')return;
 if(document.querySelector('#agent-panel'))return;
const panel=document.createElement('aside');panel.id='agent-panel';panel.setAttribute('aria-label','AI教评助手');panel.innerHTML=`<header class="agent-head"><img class="agent-avatar" src="${assistantAvatar}" alt=""><img class="agent-wordmark" src="${assistantTitle}" alt="AI教评助手"><button class="agent-return-scale" type="button" hidden aria-label="返回智能体首页" title="返回智能体首页">‹</button><button class="agent-close" aria-label="收起AI教评助手">×</button></header><section class="agent-scale-context" hidden aria-live="polite"></section><div class="agent-scroll" id="agent-messages"></div><div class="agent-skill-nav" hidden><button type="button" data-home aria-label="返回技能首页" title="返回技能首页"><img src="${assistantSkills}" alt=""><span>技能</span></button></div><form class="composer"><div class="reference-list" aria-label="引用的模块"></div><textarea aria-label="向AI教评助手提问" placeholder="请输入你的问题吧"></textarea><div class="composer-foot"><button type="submit" class="send" aria-label="发送"><img src="${assets}send.svg" alt=""></button></div><div class="agent-status" role="status" aria-live="polite"></div></form><div class="agent-note">内容由人工智能生成，仅供参考</div>`;panel.hidden=true;document.body.append(panel);
const reopen=document.createElement('button');reopen.id='agent-reopen';reopen.hidden=false;reopen.innerHTML=`<img src="${assistantAvatar}" alt="">AI教评助手`;document.body.append(reopen);
const $=s=>panel.querySelector(s);let references=[],lastPayload=null,cachedConversation='',lastSkill=null,conversationScroll=0,lastScaleAssist=null;const modules=new Map();
const dialog=document.createElement('dialog');dialog.id='agent-evidence';dialog.setAttribute('aria-labelledby','agent-proof-title');document.body.append(dialog);let trigger;
function openEvidence(title,html){trigger=document.activeElement;dialog.innerHTML=`<div class="dialog-head"><div><span class="dialog-eyebrow">AI教评助手 / 课堂依据</span><h2 id="agent-proof-title">${esc(title)}</h2></div><button class="icon-button" aria-label="关闭证据" data-proof-close>×</button></div><div class="evidence-body">${html}</div>`;dialog.showModal();}
dialog.addEventListener('close',()=>trigger?.focus({preventScroll:true}));
const skillIcons=Object.fromEntries(skills.map((s,i)=>[s,['activity','monitor-play','list-tree','flag','messages-square','files','message-circle-question','heart-handshake','clipboard-check','blocks','presentation','graduation-cap'][i]+'.svg']));
function welcome(){panel.dataset.view='home';$('.agent-skill-nav').hidden=false;const nav=$('[data-home]');nav.querySelector('span').textContent='技能';nav.setAttribute('aria-label','选择技能');nav.title='选择技能';$('#agent-messages').innerHTML=`<h2>Hi~ 我是你的AI教评助手</h2><div class="recommend-head"><span>试试这些技能</span><button type="button" data-swap>换一换 <img src="${assets}chat-regenerate.svg" alt=""></button></div><div class="skill-grid">${recommendations()}</div>`;}
function collectText(node){let text=node.innerText||'';if(node.shadowRoot)text+='\n'+node.shadowRoot.textContent;for(const e of node.querySelectorAll('*'))if(e.shadowRoot)text+='\n'+[...e.shadowRoot.querySelectorAll('h2,h3,p,text,.segment')].map(x=>x.textContent).join('\n');return text.replace(/\s*引用\s*$/,'').trim();}
function snapshot(id){const m=modules.get(id);if(!m)return null;const el=m.el;const core={summary:el.querySelector('.attitude-insight p,.phase-ai p')?.textContent||'',moduleText:collectText(el),chartLabels:[...el.querySelectorAll('svg text')].map(x=>x.textContent)};
 if(id==='method-questions'){core.statistics=stats;core.questions=questionData.questions;core.sourceStatus='报告问答示例，不与真实录像自动绑定';}
 if(id==='method-interaction'){core.events=interactionEvents;core.sourceStatus='报告互动示例，不与真实录像自动绑定';}
 if(id==='content-goals')core.goals=contentData.goals;
 if(id==='content-challenges')core.challenges=contentData.challenges;
 if(id==='content-practice')core.cases=contentData.practice;
 return {id,title:m.title,coreData:core};}
function renderRefs(){ $('.reference-list').innerHTML=references.map(r=>`<span class="ref-chip"><button type="button" data-inspect-ref="${r.id}">${esc(r.title)}</button><button type="button" class="remove-ref" data-remove-ref="${r.id}" aria-label="移除${esc(r.title)}">×</button></span>`).join('');modules.forEach((m,id)=>{const selected=references.some(r=>r.id===id);m.el.classList.toggle('agent-referenced',selected);m.button.lastChild.textContent=selected?'已引用':'引用';});}
function addReference(id){if(references.some(r=>r.id===id))return true;if(references.length>=10){$('.agent-status').textContent='最多引用10个模块，请先移除一个。';return false;}const ref=snapshot(id);if(!ref)return false;references.push(ref);$('.agent-status').textContent='';renderRefs();return true;}
function mountReferences(){document.querySelectorAll('main:not(#recording):not(#overview)').forEach(main=>{const candidates=[...main.querySelectorAll(':scope > section.card')];if(main.id==='literacy')candidates.push(...main.querySelectorAll('.content-detail-card[id]'));for(const el of candidates){const heading=el.querySelector('h2,h3');if(!heading||!el.id||el.id==='content-quality'||el.hidden||el.id.endsWith('-legacy')||modules.has(el.id))continue;const title=heading.textContent.trim();if(/^(教学态度|教学内容|教学方法|教学素养|教学效果)$/.test(title))continue;const b=document.createElement('button');b.type='button';b.className='agent-cite';b.dataset.cite=el.id;b.setAttribute('aria-label',`引用${title}模块`);b.innerHTML=`<img src="${star}" alt=""><span>引用</span>`;el.classList.add('agent-citable');el.append(b);modules.set(el.id,{el,title,button:b});}});}
function contextPayload(question,skill=null){return {course:'智慧医疗',skill,question,references:references.map(r=>({...r})),asr:{source:'recording-transcript-data.js',segments:recordingTranscript},scope:'local-design-preview'};}
function answerChart(){return `<button class="answer-chart" data-proof="chart"><span class="evidence-meta">提问认知层级 <span>30次教师提问</span></span>${bloomLabels.map((label,i)=>`<span class="chart-row"><span>${label}</span><span class="chart-track"><span class="chart-fill" style="display:block;width:${stats.bloom[i]/30*100}%"></span></span><span>${stats.bloom[i]}次</span></span>`).join('')}</button>`;}
function screenCard(){return `<button class="evidence-card" data-proof="screen"><span class="evidence-meta">课件画面<time>02:00</time></span><b>MYCIN专家系统</b><img src="assets/recording-real/3-120.jpg" alt="MYCIN专家系统课件截图"></button>`;}
function renderAnswer(name,userText){const s=preset[name];lastSkill=name;panel.dataset.view='conversation';$('.agent-skill-nav').hidden=false;const nav=$('[data-home]');nav.querySelector('span').textContent='技能';nav.setAttribute('aria-label','选择技能');nav.title='返回技能首页';lastPayload=contextPayload(userText||`请分析本课的${name}`,name);$('#agent-messages').innerHTML=`<div class="user-message">${esc(lastPayload.question)}</div><article class="answer"><div class="answer-progress"><div>${doneIcon}分析教评报告数据</div><div>${doneIcon}分析语音转写数据</div></div><div class="answer-body"><p>${s.lead}</p><h3>本课表现</h3><p>${s.good}</p>${s.kind==='screen'?screenCard():s.kind==='interaction'||s.kind==='question'?answerChart():''}<h3>问题与建议</h3><p>${s.issue}</p>${s.kind==='interaction'?`<button class="evidence-card" data-proof="interaction"><span class="evidence-meta">问答记录<time>24:10–25:16</time></span><b>检索资料冲突：学生提出、同伴补充</b></button>`:s.kind==='question'?`<button class="evidence-card" data-proof="question"><span class="evidence-meta">教师提问与学生应答<time>${fmt(questionData.questions[2].start)}</time></span><b>怎样判断一个医疗问答结果是否可靠？</b></button>`:`<button class="evidence-card" data-proof="asr"><span class="evidence-meta">课堂转写<time>${fmt(recordingTranscript[1].time)}</time></span><b>人工智能历程：从知识驱动到数据驱动</b></button>`}</div><div class="answer-actions">${answerActions()}</div></article>`;$('#agent-messages').scrollTop=0;}
const scaleEvidence={
 1:{refs:[],clips:[]},2:{refs:['method-multimedia'],clips:[{kind:'PPT',time:120,title:'MYCIN专家系统课件画面'}]},3:{refs:['attitude-management'],clips:[]},4:{refs:['literacy-values'],clips:[]},5:{refs:['content-goals'],clips:[]},6:{refs:['content-features'],clips:[{kind:'ASR',time:360,title:'从知识驱动到数据驱动'}]},7:{refs:['content-challenges'],clips:[]},8:{refs:['method-language','attitude-body'],clips:[]},9:{refs:['method-multimedia'],clips:[{kind:'PPT',time:120,title:'MYCIN专家系统课件画面'}]},10:{refs:['content-practice'],clips:[{kind:'ASR',time:360,title:'人工智能发展与医疗应用'}]},11:{refs:['method-questions','method-interaction'],clips:[]},12:{refs:['content-goals'],clips:[]},13:{refs:[],clips:[]},14:{refs:['method-interaction','effect-state'],clips:[]},15:{refs:['effect-monitoring','effect-state'],clips:[]},16:{refs:[],clips:[]},17:{refs:[],clips:[]}
};
function renderScaleAssist(detail,followup=''){
 const evidence=scaleEvidence[detail.number]||{refs:[],clips:[]};
 lastScaleAssist=detail;lastSkill=null;panel.dataset.view='conversation';$('.agent-skill-nav').hidden=false;references=[];evidence.refs.forEach(addReference);renderRefs();
 const context=$('.agent-scale-context');context.hidden=false;context.innerHTML=`<span>当前辅助评价</span><strong>量表第${detail.number}题 · ${detail.max??'主观评价'}${detail.max?'分':''}</strong><p>${esc(detail.text)}</p>`;
 const prompt=followup||(detail.max===null?`请结合报告证据模拟评价第${detail.number}题，并给出可编辑的主观评价。`:`请结合报告证据辅助评价第${detail.number}题，并说明建议分数和依据。`);
 const suggested=detail.max===10?8:detail.max===5?4:null;
 const subjectiveDraft=detail.number===16?'本课结合智慧医疗案例组织教学，能够将行业应用情境带入课堂，并通过问题讨论引导学生分析技术方案与实际需求的联系。现有报告暂未记录企业专家参与或完整项目化学习成果，建议结合任务单、学生作品与现场观察进一步确认产教融合的深度。':'本课使用人工智能发展与智慧医疗案例帮助学生理解学科前沿，体现了将专业研究素材转化为课堂内容的尝试。现有报告暂未发现学生直接参与教师课题或科研成果转化的完整证据，建议结合课题任务、学生产出及课堂原始记录补充评价。';
 const hasEvidence=references.length+evidence.clips.length>0;
 const answer=followup?`结合你补充的问题，${hasEvidence?'建议继续核对下列直接相关证据':'当前报告仍未找到能直接支撑本题判断的内容'}。${suggested!==null&&hasEvidence?`当前建议维持 <strong>${suggested} 分</strong>。`:''}最终评价以督导核实后的完整课堂证据为准。${detail.max===null&&hasEvidence?`<h3>模拟评价</h3><p>${subjectiveDraft}</p>`:''}`:!hasEvidence?`当前报告、ASR 转写和 PPT 中均未找到与本题直接相关、足以支撑评价的内容，因此不推荐关联模块或给出确定分数。建议结合现场观察及补充材料后人工评价。`:detail.max===null?`当前证据与本题存在直接关联。以下为可继续追问和修改的模拟评价，不会自动写入量表。<h3>模拟评价</h3><p>${subjectiveDraft}</p>`:`当前报告能够为本题提供直接相关的部分依据。综合现有证据，建议 <strong>${suggested} 分</strong>；最终分数仍需结合视频回放和督导现场观察确认。`;
 const moduleCards=references.map(r=>`<button class="evidence-card" data-scale-jump="#${r.id}"><span class="evidence-meta">报告模块 <span>跳转查看 ↗</span></span><b>${esc(r.title)}</b></button>`).join('');
 const clipCards=evidence.clips.map(clip=>`<button class="evidence-card" data-video-time="${clip.time}"><span class="evidence-meta">${clip.kind} 证据 <time>${fmt(clip.time)} · 跳转 ↗</time></span><b>${esc(clip.title)}</b></button>`).join('');
 $('#agent-messages').innerHTML=`<div class="user-message"><small>量表第${detail.number}题 · ${detail.max??'主观评价'}${detail.max?'分':''}</small><br>${esc(prompt)}</div><article class="answer"><div class="answer-progress"><div>${doneIcon}${hasEvidence?`找到 ${references.length+evidence.clips.length} 项直接相关证据`:'未找到直接相关证据'}</div><div>${doneIcon}已检查报告、ASR 与 PPT</div></div><div class="answer-body"><p>${answer}</p><h3>相关证据</h3>${hasEvidence?moduleCards+clipCards:'<p class="answer-source">暂无可关联内容</p>'}<p class="answer-source">可以继续追问或补充现场观察。AI 建议不会自动写入量表。</p></div><div class="answer-actions">${answerActions()}</div></article>`;
 $('textarea').value='';$('.agent-status').textContent='';$('#agent-messages').scrollTop=0;
}
panel.addEventListener('click',e=>{const skill=e.target.closest('[data-skill]');if(skill){selectSkill(skill.dataset.skill);return;}if(e.target.closest('[data-home]')){navigateHome();return;}const remove=e.target.closest('[data-remove-ref]');if(remove){references=references.filter(r=>r.id!==remove.dataset.removeRef);renderRefs();$('.agent-status').textContent='';return;}const inspect=e.target.closest('[data-inspect-ref]');if(inspect){const r=references.find(x=>x.id===inspect.dataset.inspectRef);if(r)openEvidence(`引用 · ${r.title}`,`<h3>核心数据</h3><div class="core-data">${esc(r.coreData.statistics?`教师提问 ${stats.questions}次 · 学生应答 ${stats.answers}次\n记录到应答 ${stats.responded}/${stats.questions}题\n教师追问 ${stats.followups}次\n\n`:'')}${esc(r.coreData.moduleText||r.coreData.summary||'当前模块无可用结果')}</div><h3>输入范围</h3><p>模块结论、图表数值、关联记录与当前课堂转写。</p>`);return;}const proof=e.target.closest('[data-proof]');if(proof)showProof(proof.dataset.proof);});
function showProof(kind){if(kind==='screen'){openEvidence('MYCIN专家系统 · 02:00',`<img class="proof-image" src="assets/recording-real/3-120.jpg" alt="MYCIN专家系统课件画面"><h3>画面依据</h3><p>课件呈现MYCIN专家系统及其医疗诊断应用，支持“案例与智慧医疗内容相联系”的判断。</p><p>单张画面不能证明学生已经理解或能够迁移应用。</p><button class="video-target" data-video-time="120">定位课堂录像 · 02:00</button>`);return;}
 if(kind==='interaction'){const ev=interactionEvents[0];openEvidence('资料冲突讨论',`<p>${ev.reason}</p>${ev.turns.map(t=>`<article class="proof-row"><span class="proof-time">${fmt(t[1])} · ${esc(t[2])}</span><p>${esc(t[3])}</p><p>${esc(t[4])}</p></article>`).join('')}<p>此问答记录为报告示例，暂无可核验的对应视频。</p>`);return;}
 if(kind==='question'||kind==='chart'){const q=questionData.questions[2];openEvidence(kind==='chart'?'提问认知层级与课堂记录':q.text,`${kind==='chart'?`<p>${bloomLabels.map((l,i)=>`${l} ${stats.bloom[i]}次`).join(' · ')}。认知层级依据问题所要求的思维活动，不直接代表回答质量。</p>`:''}<h3>${esc(q.text)}</h3>${q.turns.map(t=>`<article class="proof-row"><span class="proof-time">${fmt(t.start)} · ${t.role==='teacher'?'教师':'学生'}</span><p>${esc(t.text)}</p></article>`).join('')}<p>学生将权威资料核对与适用条件联系起来；这只能支撑当前回答表现，不推断全班掌握。该问答为报告示例，暂无可核验的对应视频。</p>`);return;}
 const row=recordingTranscript[1];openEvidence('课堂转写 · '+fmt(row.time),`<span class="proof-time">${fmt(row.time)} · ${esc(row.speaker)}</span><p>${esc(row.text)}</p><h3>前文</h3><p>${esc(recordingTranscript[0].text)}</p><h3>后文</h3><p>${esc(recordingTranscript[2].text)}</p><button class="video-target" data-video-time="${row.time}">定位课堂录像 · ${fmt(row.time)}</button>`);}
document.addEventListener('click',e=>{const cite=e.target.closest('[data-cite]');if(cite){e.preventDefault();e.stopImmediatePropagation();addReference(cite.dataset.cite);panel.hidden=false;reopen.hidden=true;document.body.classList.add('agent-open');if(document.body.classList.contains('scale-v8-open'))document.body.classList.add('scale-agent-coexist');}if(e.target.closest('[data-proof-close]'))dialog.close();const video=e.target.closest('[data-video-time]');if(video){dialog.close();location.hash='recording';requestAnimationFrame(()=>{const v=document.querySelector('#real-classroom-video');if(v&&v.readyState>=1){v.pause();v.currentTime=Number(video.dataset.videoTime);$('.agent-status').textContent=`已定位课堂录像 ${fmt(v.currentTime)}`;}else $('.agent-status').textContent='录像暂未加载完成，请在课堂实录中重试定位。';});}},true);
$('.agent-close').addEventListener('click',()=>{panel.hidden=true;reopen.hidden=false;$('.agent-return-scale').hidden=true;$('.agent-scale-context').hidden=true;lastScaleAssist=null;document.body.classList.remove('agent-open','scale-agent-coexist');const scalePanel=document.querySelector('#scale-v8-panel');const scaleEntry=document.querySelector('#scale-v8-entry');if(scaleEntry&&location.hash!=='#recording'&&(scalePanel?.hidden??true))scaleEntry.hidden=false;reopen.focus();});reopen.addEventListener('click',()=>{panel.hidden=false;reopen.hidden=true;$('.agent-return-scale').hidden=true;$('.agent-scale-context').hidden=true;lastScaleAssist=null;const scalePanel=document.querySelector('#scale-v8-panel');const scaleEntry=document.querySelector('#scale-v8-entry');if(scaleEntry&&location.hash!=='#recording')scaleEntry.hidden=!(scalePanel?.hidden??true);document.body.classList.add('agent-open');if(scalePanel&&!scalePanel.hidden)document.body.classList.add('scale-agent-coexist');$('.agent-close').focus();});
$('.agent-return-scale').addEventListener('click',()=>{$('.agent-return-scale').hidden=true;$('.agent-scale-context').hidden=true;lastScaleAssist=null;lastSkill=null;references=[];renderRefs();welcome();});
$('.composer').addEventListener('submit',async e=>{e.preventDefault();const q=$('textarea').value.trim();if(!q){$('.agent-status').textContent='请输入问题或选择一个技能。';return;}if(lastScaleAssist){renderScaleAssist(lastScaleAssist,q);return;}if(pendingSkill){renderAnswer(pendingSkill,q);$('textarea').value='';$('.agent-status').textContent='';return;}lastPayload=contextPayload(q);const send=$('.send');send.disabled=true;$('.agent-status').textContent='正在分析…';try{const response=await fetch('/api/agent/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(lastPayload)});const data=await response.json();if(!response.ok)throw new Error(data.error||'AI 服务暂时不可用');panel.dataset.view='conversation';$('#agent-messages').innerHTML=`<div class="user-message">${esc(q)}</div><article class="answer"><div class="answer-body api-answer"><p>${esc(data.content).replace(/\n{2,}/g,'</p><p>').replace(/\n/g,'<br>')}</p></div><div class="answer-actions">${answerActions()}</div></article>`;$('textarea').value='';$('.agent-status').textContent='';}catch(error){$('.agent-status').textContent=error.message||'AI 服务暂时不可用';}finally{send.disabled=false;}});
function answerActions(){return [['like','点赞'],['dislike','点踩'],['copy','复制'],['regenerate','重新生成']].map(([action,label])=>`<button type="button" data-answer-action="${action}" aria-label="${label}" title="${label}" ${['like','dislike'].includes(action)?'aria-pressed="false"':''}><img src="${assets}chat-${action}.svg" alt=""></button>`).join('');}
function navigateHome(){const open=!$('.skill-picker');if(!open){closeSkillPicker();return;}const picker=document.createElement('section');picker.className='skill-picker';picker.setAttribute('aria-label','选择技能');picker.innerHTML=`<header><strong>选择技能</strong><button type="button" data-picker-close aria-label="关闭技能选择">×</button></header><div class="picker-list">${skills.map(s=>`<button type="button" data-skill="${s}" aria-pressed="${pendingSkill===s}">${s}<span aria-hidden="true">›</span></button>`).join('')}</div>`;panel.insertBefore(picker,$('.agent-skill-nav'));$('[data-home]').setAttribute('aria-expanded','true');picker.querySelector('button').focus();}
panel.addEventListener('click',async e=>{const button=e.target.closest('[data-answer-action]');if(!button)return;const action=button.dataset.answerAction;if(action==='like'||action==='dislike'){const active=button.getAttribute('aria-pressed')!=='true';panel.querySelectorAll('[data-answer-action="like"],[data-answer-action="dislike"]').forEach(b=>b.setAttribute('aria-pressed',String(b===button&&active)));}else if(action==='copy'){try{await navigator.clipboard.writeText($('.answer-body').innerText);button.title='已复制';button.setAttribute('aria-label','已复制');}catch{$('.agent-status').textContent='复制未成功，请选择正文复制。';}}else if(lastSkill){renderAnswer(lastSkill);}});
let recommendedSkills=skills.slice(0,4),pendingSkill=null;
function shuffleRecommendations(){const pool=skills.filter(s=>!recommendedSkills.includes(s));for(let i=pool.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[pool[i],pool[j]]=[pool[j],pool[i]];}recommendedSkills=pool.slice(0,4);}
const skillSubtitles={
 '学生学习状态':'学生投入吗？看看专注与参与表现',
 '多媒体运用':'课件用得合适吗？看看是否帮助理解',
 '教学内容组织':'内容讲顺了吗？梳理知识与环节衔接',
 '课程思政':'如何结合专业内容，自然融入价值引导？',
 '师生互动分析':'互动有深度吗？看看回应与交流过程',
 '教学资料准备':'资料准备充分吗？看看还需要补什么',
 '提问技能':'怎样问得更好？看看问题设计与追问',
 '教师教学投入':'教师投入如何？结合情感与巡堂看看',
 '课程大纲对比':'这节课与大纲要求对得上吗？',
 '理论联系实际':'案例讲透了吗？看看理论如何落到应用',
 '教学方式':'教法适合这节课吗？看看如何调整',
 '学习达成情况':'学生学会了吗？结合回答与任务判断'
};
function recommendations(){return recommendedSkills.map(s=>`<button type="button" class="skill" data-skill="${s}"><span class="skill-symbol symbol-${skills.indexOf(s)%6}"><img class="skill-icon" src="${assets}skill-icons/${skillIcons[s]}" alt=""></span><span class="skill-copy"><strong>${s}</strong><small>${skillSubtitles[s]}</small></span></button>`).join('');}
function closeSkillPicker(){ $('.skill-picker')?.remove();$('[data-home]').setAttribute('aria-expanded','false');}
function selectSkill(name){pendingSkill=null;references=[];renderRefs();$('.selected-skill')?.remove();$('textarea').value='';$('.agent-status').textContent='';closeSkillPicker();$('.agent-return-scale').hidden=false;renderAnswer(name,`分析${name}`);}
panel.addEventListener('click',e=>{if(e.target.closest('[data-swap]')){shuffleRecommendations();$('.skill-grid').innerHTML=recommendations();}if(e.target.closest('[data-picker-close]')){closeSkillPicker();$('[data-home]').focus();}if(e.target.closest('[data-clear-skill]')){pendingSkill=null;$('.selected-skill')?.remove();$('textarea').value='';}});
panel.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('.skill-picker')){e.preventDefault();closeSkillPicker();$('[data-home]').focus();}});
mountReferences();welcome();
document.addEventListener('agent:scale-assist',event=>{panel.hidden=false;reopen.hidden=true;$('.agent-return-scale').hidden=false;const scaleEntry=document.querySelector('#scale-v8-entry');if(scaleEntry)scaleEntry.hidden=true;document.body.classList.add('agent-open');if(event.detail?.embedded){document.body.classList.remove('scale-v8-open','scale-agent-coexist');}else{document.body.classList.add('scale-v8-open','scale-agent-coexist');}renderScaleAssist(event.detail);});
window.agentDesign={get references(){return references;},get payload(){return lastPayload;},get modules(){return [...modules.keys()];},ready:true};

}
